151: function isWaypointSlotEnabled(currentCount: number, slot: 0 | 1 | 2): boolean {
152:   if (slot < currentCount) return true;
153:   if (slot === currentCount && currentCount < MAX_ROUTE_WAYPOINTS) return true;
154:   return false;
155: }
156: 
157: function waypointSlotTitle(slot: 0 | 1 | 2, count: number): string {
158:   if (isWaypointSlotEnabled(count, slot)) {
159:     return slot < count
160:       ? `Move waypoint ${slot + 1} here`
161:       : `Add waypoint ${slot + 1} here`;
162:   }
163:   if (slot > count) {
164:     return `Set WP${count + 1} before WP${slot + 1}`;
165:   }
166:   return "No more waypoints";
167: }
