199:   getLabel: (publicationId: string, kind: "pulse" | "heat") => string | null,
200:   popupRef: { current: mapboxgl.Popup | null },
201:   pickAnchor: (map: mapboxgl.Map, event: mapboxgl.MapMouseEvent) => mapboxgl.Anchor,
202: ): boolean {
203:   const layers = [ACTIVITY_PULSE_DOTS_LAYER, ACTIVITY_HEAT_DOTS_LAYER].filter((id) =>
204:     map.getLayer(id),
205:   );
206:   if (!layers.length) return false;
207:   const features = map.queryRenderedFeatures(event.point, { layers });
208:   if (!features.length) return false;
209:   const hit = features[0];
210:   const publicationId = hit.properties?.publicationId;
211:   if (typeof publicationId !== "string" || !publicationId.trim()) return false;
212:   const kind: "pulse" | "heat" = hit.layer?.id === ACTIVITY_HEAT_DOTS_LAYER ? "heat" : "pulse";
213:   const label = getLabel(publicationId.trim(), kind);
214:   if (!label) return false;
215: 
216:   popupRef.current?.remove();
217:   const popup = new mapboxgl.Popup({
218:     closeOnClick: true,
219:     className: "map-view__activity-popup-wrap",
220:     maxWidth: "min(16rem, calc(100vw - 1.5rem))",
221:     anchor: pickAnchor(map, event),
222:     offset: 12,
223:   })
224:     .setLngLat(event.lngLat)
225:     .setDOMContent(buildActivityWorldPopupElement(label, kind))
226:     .addTo(map);
227:   popup.on("close", () => {
228:     if (popupRef.current === popup) popupRef.current = null;
229:   });
230:   popupRef.current = popup;
231:   return true;
232: }
