  if (routePickAuxExpanded === next) {
    syncRoutePickView();
    return;
  }
  routePickAuxExpanded = next;
  syncRoutePickView();
}

routePickCaret.onclick = () => {
  setRoutePickAuxExpanded(!routePickAuxExpanded);
